  var d=CriliumDefinition.Load;d.Journal.Quests[0].Giver=npc.Id;d.Journal.Quests[0].Description="Partí desde Vitral: hablá con el guía, cruzá el borde de Saara Woods y seguí el sendero hacia las dunas. El centinela custodia el paso; algo del Rift está por irrumpir en el cielo.";EditorUtility.SetDirty(d.Journal.Quests[0]);
  var list=d.Lessons.ToList();if(!list.Any(l=>l.Lesson==CriliumLesson.Introduction))list.Insert(2,new CriliumLessonDefinition{Lesson=CriliumLesson.Introduction,Title="El guía de Vitral",Instruction="Seleccioná al guía, hablá con {Interact} y aceptá su misión. Después cerrá el diálogo.",Help="Un NPC no es un enemigo. Podés seleccionarlo con clic e interactuar a corta distancia. El diálogo muestra su misión; aceptar y seguir son acciones distintas.",Goal=npc.transform.position,ArrivalRadius=5});list.RemoveAll(l=>l.Lesson==CriliumLesson.Map);d.Lessons=list.ToArray();d.Lessons[0].Goal=new Vector3(0,0,9);d.Lessons[0].ArrivalRadius=2;d.Lessons[0].Title="Primeros pasos en Vitral";d.Lessons[1].Goal=new Vector3(0,0,12);d.Lessons[1].ArrivalRadius=6;var nav=d.Lessons.First(l=>l.Lesson==CriliumLesson.Journal);nav.Title="Diario, mapa y minimapa";nav.Instruction="Abrí y seguí tu misión en el diario ({Journal}); cerralo y consultá el mapa ({WorldMap}).";nav.Help="Primero revisá objetivos en el diario. Después cerralo y abrí el mapa para ver tu posición y la señal violeta. El tracker queda bajo el minimapa; no hace falta abrir ambas ventanas a la vez.";
  var director=UnityEngine.Object.FindFirstObjectByType<CriliumDirector>();var fall=director.GetComponent<CriliumRiftFall>();if(!fall)fall=director.gameObject.AddComponent<CriliumRiftFall>();var previous=GameObject.Find("Crelium falling Rift fragment");if(previous)UnityEngine.Object.DestroyImmediate(previous);var root=new GameObject("Crelium falling Rift fragment").transform;
  fall.ImpactPoint=new GameObject("Rift impact location").transform;fall.ImpactPoint.SetParent(root);fall.ImpactPoint.position=new Vector3(0,0,201);fall.FlightStart=new GameObject("Rift fragment sky origin").transform;fall.FlightStart.SetParent(root);fall.FlightStart.position=new Vector3(58,95,270);
  fall.Fragment=new GameObject("Physical Rift fragment").transform;fall.Fragment.SetParent(root);fall.Fragment.position=fall.ImpactPoint.position;var rock=(GameObject)PrefabUtility.InstantiatePrefab(Prefab("Rock_Boulder_C"));PrefabUtility.UnpackPrefabInstance(rock,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);rock.transform.SetParent(fall.Fragment);var rb=Bounds(rock);rock.transform.localScale*=2.8f/Mathf.Max(rb.size.x,Mathf.Max(rb.size.y,rb.size.z));rb=Bounds(rock);rock.transform.position+=fall.Fragment.position-rb.center;foreach(var c in rock.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);
