  fall.Portal=director.ExitPortal;fall.Portal.position=new Vector3(0,2,203);fall.ResetWorld();var end=d.Lessons.Last();end.Goal=fall.ImpactPoint.position;end.Title="El lugar del impacto";end.Instruction="Investigá el fragmento caído. Acercate a la grieta para cruzar al Rift.";end.Help="El fragmento abrió un paso. Tu poder sigue intacto hasta cruzarlo: el Rift se lo arrebata a Nertör al ingresar.";EditorUtility.SetDirty(d);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("CRELIUM VITRAL AND FRAGMENT MOUNTED - mission server catalog remains a known pending dependency");
