 public static void Capture(){Directory.CreateDirectory(Output);EditorSceneManager.OpenScene(CriliumSession.ScenePath,OpenSceneMode.Single);var fall=UnityEngine.Object.FindFirstObjectByType<CriliumRiftFall>();fall.Preview(.58f);Photo("Crelium-08-caida-fragmento-editor.png",new Vector3(20,28,155),fall.Fragment.position,55);fall.Preview(1);Simulate(fall,.28f);Photo("Crelium-09-impacto-fragmento-editor.png",new Vector3(20,10,179),new Vector3(0,2,201),60);Simulate(fall,1.5f);Photo("Crelium-10-acercamiento-fragmento-editor.png",new Vector3(0,3.5f,190),new Vector3(0,1.8f,202),60);fall.ResetWorld();Photo("Crelium-11-inicio-Vitral-editor.png",new Vector3(-6,4,-7),new Vector3(2,3,15),64);Debug.Log("CRELIUM FRAGMENT AND VITRAL REAL EDITOR CAPTURES SAVED");}
 static void Simulate(CriliumRiftFall fall,float seconds){foreach(var ps in fall.ImpactEffect.GetComponentsInChildren<ParticleSystem>()){ps.Simulate(seconds,false,true,true);ps.Pause();}foreach(var ps in fall.Portal.GetComponentsInChildren<ParticleSystem>()){ps.Simulate(seconds,false,true,true);ps.Pause();}}
 static void Photo(string name,Vector3 position,Vector3 target,float fov){var go=new GameObject("Temporary fragment photo camera");var camera=go.AddComponent<Camera>();camera.transform.position=position;camera.transform.LookAt(target);camera.fieldOfView=fov;camera.clearFlags=CameraClearFlags.Skybox;camera.nearClipPlane=.1f;camera.farClipPlane=2000;var rt=new RenderTexture(1920,1080,24);camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1920,1080,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1920,1080),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Output,name),t.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}
